    {
        if (actionId == ACTION_ENCOUNTER_COMPLETE)
        {
            if (instance->GetBossState(DATA_EONAR) != DONE)
            {
                instance->SetBossState(DATA_EONAR, DONE);

                instance->HandleGameObject(instance->GetGuidData(GO_EONAR_PARAXIS_DOOR_1), true);
