                    events.RescheduleEvent(EVENT_SEVER, 7000);
                    break;
                case EVENT_SHRAPNEL_BLAST:
                    DoCast(SPELL_SHRAPNEL_BLAST);
                    events.RescheduleEvent(EVENT_SHRAPNEL_BLAST, 14000);
                    break;
                case EVENT_CHARGED_BLASTS:
                    DoCast(SPELL_CHARGED_BLASTS);
